    "id": "wiki.crm-pipeline-stages",
    "objectId": "wiki.crm-pipeline-stages",
    "title": "CRM Pipeline Stages",
    "description": "Approved two-part CRM lifecycle: leads move through Contract & Signature, then signed records carry into the client path from Client Kickoff through first metrics capture.",
    "category": "wiki-sales",
    "status": "draft",
    "publishBucket": "internal-draft",
    "reviewer": "Samir / Adrian / Max",
