    "id": "wiki.block-ops-wiki-compendium",
    "objectId": "wiki.block-ops-wiki-compendium",
    "title": "Block Ops Wiki / Compendium",
    "description": "The Block Ops Wiki is the internal company knowledge system.",
    "category": "wiki-platform",
